package telemetry

import (
	"context"
	"encoding/json"
	"strings"
	"testing"

	"github.com/mjaffry01/mindsuite-doctrine-of-legacy-modernization/backend/internal/agents"
)

// TestTelemetryRun runs the team (without a model) on testdata/sample: 12 months of hourly Splunk
// counts with a harvest season and a 10-day gap, one day of NGINX access log, and a little code.
// The sample is generated by a script (see the commit) with known answers.
func TestTelemetryRun(t *testing.T) {
	code, err := agents.LoadDir("testdata/sample")
	if err != nil {
		t.Fatal(err)
	}
	r, err := agents.NewRun(code, agents.Options{Team: "telemetry"}, nil, "")
	if err != nil {
		t.Fatal(err)
	}
	r.Execute(context.Background())
	snap := r.Snapshot()
	if snap.Run.Status != "done" {
		t.Fatalf("status %s: %s", snap.Run.Status, snap.Run.Error)
	}
	if len(snap.Agents) != 11 || snap.Agents[1].ID != "ing" {
		t.Errorf("telemetry team expected, got %d agents", len(snap.Agents))
	}
	byKind := map[string][]agents.Finding{}
	for _, f := range snap.Findings {
		byKind[f.Kind] = append(byKind[f.Kind], f)
		if f.Status == StatusProposed {
			t.Errorf("not verified: %s %s", f.ID, f.Title)
		}
		if f.Status == StatusRejected {
			t.Errorf("rejected: %s %s — %s", f.ID, f.Title, f.Verdict)
		}
	}
	has := func(kind, sub string) {
		t.Helper()
		for _, f := range byKind[kind] {
			if strings.Contains(f.Title+" "+f.Detail, sub) {
				return
			}
		}
		titles := []string{}
		for _, f := range byKind[kind] {
			titles = append(titles, f.Title+" | "+f.Detail)
		}
		t.Errorf("missing %s containing %q; have %v", kind, sub, titles)
	}
	has("telemetry-window", "from 2025-11-01 to 2026-10-31 (365 days)")
	has("load-profile", "peak 0.50 requests per second")
	has("load-profile", "Mon 14 Sep 2026 09:00")
	has("peak-hours", "Busiest hours: 09:00, 08:00, 10:00")
	has("quiet-window", "Sunday 01:00–05:00 UTC")
	has("peak-months", "August, September, October")
	has("response-times", "typical 95th percentile 420 ms (worst slot 850 ms)")
	has("response-times", "95th percentile 2600 ms") // from the access log, shown alongside
	has("slow-endpoint", "GET /api/reports/yearly")
	has("error-rate", "Error rate")
	has("failing-endpoint", "POST /api/payments/run fails 35%")
	has("top-endpoints", "POST /api/deliveries (41%)")
	has("top-endpoints", "GET /api/lots/{id}")
	has("top-endpoints", "GET /api/growers/{id}/statement")
	has("rarely-used", "GET /api/admin/legacy-export (1)")
	has("distinct-clients", "About 120 distinct client addresses")
	has("unused-endpoint", "/api/export/csv")
	has("unused-endpoint", "/api/lots/archive")
	has("data-gaps", "longest gap is 240 hours with no data, from 5 Feb 2026 00:00 to 14 Feb 2026 23:00")
	has("secret", "monitoring.properties line 2")
	has("capacity-target", "Design for 0.8 requests per second")
	has("slo-target", "95% of requests under")
	has("cut-over", "avoid August, September, October")
	has("cut-over", "Sunday 01:00–05:00 UTC")
	has("migration-approach", "measured peaks")
	for _, f := range byKind["top-endpoints"] {
		if strings.Contains(f.Detail, "static") {
			t.Error("static files must not count as a business endpoint")
		}
	}
	for _, f := range byKind["unused-endpoint"] {
		if strings.Contains(f.Detail, "/api/deliveries") || strings.Contains(f.Detail, "/api/lots/{id}") {
			t.Errorf("called endpoints listed as unused: %s", f.Detail)
		}
	}
	b, _ := json.Marshal(snap)
	out := string(b) + r.Report
	for _, leak := range []string{"SplunkPa55word", "10.0.1.", "10.0.2.", "@example.com", "token=Zx81abc", "/api/lots/1001"} {
		if strings.Contains(out, leak) {
			t.Errorf("personal data or a secret leaked into the result: %q", leak)
		}
	}
	if snap.Run.Steps[4].Status != "skipped" {
		t.Errorf("step 5 should be skipped without a model, got %s", snap.Run.Steps[4].Status)
	}
	if !strings.Contains(r.Report, "# Telemetry analysis report") || !strings.Contains(r.Report, "Capacity, service levels and cut-over") {
		t.Error("report incomplete")
	}
}
